style.css:
/* General background color */
body {
    background-color: #1a1a2e !important; /* Dark navy/black tone */
    color: #ffffff !important; /* White text */
    font-family: "Georgia", serif !important; /* Elegant font */
}

/* Change links to silver */
a {
    color: #c0c0c0 !important;
    text-decoration: none !important;
}

a:hover {
    color: #ffffff !important;
    text-decoration: underline !important;
}

/* Box styling for a luxury aesthetic */
div, section, header, footer {
    background-color: rgba(26, 26, 46, 0.8) !important;
    border: 1px solid #c0c0c0 !important;
    border-radius: 8px !important;
    padding: 10px !important;
}

/* Button Styling */
button {
    background-color: #333366 !important; /* Dark blue */
    color: #ffffff !important;
    border: 1px solid #c0c0c0 !important;
    padding: 8px 12px !important;
    border-radius: 5px !important;
    font-weight: bold !important;
}

button:hover {
    background-color: #555599 !important;
}

/* Customize scrollbar for a sleek look */
::-webkit-scrollbar {
    width: 8px;
}

::-webkit-scrollbar-track {
    background: #1a1a2e;
}

::-webkit-scrollbar-thumb {
    background: #555599;
    border-radius: 5px;
}
